describe('Product List Display - Inventory Page', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-testid="login-form"]').within(() => {
      cy.get('[data-testid="email-input"]').type('standard_user@example.com');
      cy.get('[data-testid="password-input"]').type('secret_sauce');
      cy.get('[data-testid="login-button"]').click();
    });
  });

  it('should display complete product cards with non-empty names and prices starting with $', () => {
    cy.get('[data-testid="inventory-list"]').should('be.visible');
    cy.get('[data-testid="inventory-item"]').should('have.length.exactly', 6);

    cy.get('[data-testid="inventory-item"]').each(($item, index) => {
      cy.get(`[data-testid="inventory-item-name"]`).should('be.visible');
      cy.get(`[data-testid="inventory-item-name"]`).should('contain.text');

      cy.get(`[data-testid="inventory-item-price"]`).should('be.visible');
      cy.get(`[data-testid="inventory-item-price"]`).should('contain.text');
      cy.get(`[data-testid="inventory-item-price"]`).should('startWith', '$');

      cy.get(`[data-testid="inventory-item-name"]`).should('have.length.greaterThan', 0);
      cy.get(`[data-testid="inventory-item-price"]`).should('have.length.greaterThan', 0);
    });
  });

  it('should handle empty inventory list gracefully', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-testid="inventory-list"]').should('be.visible');

    cy.get('[data-testid="inventory-item"]').should('not.exist');

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'No products available');
  });
});
